def migrate_portal_registry(apps, schema_editor):
    GameDestination = apps.get_model('ducky_arenas', 'GameDestination')
    Portal = apps.get_model('ducky_arenas', 'Portal')
    database = schema_editor.connection.alias
    configured = {}
    for code, name, owner_app, description in DESTINATIONS:
        route_name = 'duckyclash:home' if code == 'clash' else ''
        defaults = {
            'name': name,
            'description': description,
            'owner_app': owner_app,
            'entry_url_name': route_name,
            'status': 'available' if route_name else 'pending',
            'access_requirements': {},
            'icon_path': '',
            'entry_behavior': 'same_tab',
            'return_behavior': 'core_checkpoint',
        }
        destination, _ = GameDestination.objects.using(database).get_or_create(
            code=code,
            defaults=defaults,
        )
        configured[owner_app] = destination

    for portal in Portal.objects.using(database).select_related('world_map').all():
        destination = configured.get(portal.destination_app)
        if destination is None:
            code = slugify(portal.destination_app)[:64] or f'legacy-{portal.pk}'
            destination, _ = GameDestination.objects.using(database).get_or_create(
                code=code,
                defaults={
                    'name': portal.destination_app,
                    'description': 'Destino migrado; requiere revisión administrativa.',
                    'owner_app': portal.destination_app,
                    'entry_url_name': '',
                    'status': 'pending',
                    'access_requirements': {},
                    'icon_path': '',
                    'entry_behavior': 'same_tab',
                    'return_behavior': 'core_checkpoint',
                },
            )
        portal.destination_id = destination.pk
        if portal.destination_url_name and (
            portal.destination_url_name != destination.entry_url_name
            or destination.status != 'available'
        ):
            destination.entry_url_name = ''
            destination.status = 'pending'
            destination.save(
                using=database,
                update_fields=['entry_url_name', 'status'],
            )

        dimensions = (portal.world_map.width, portal.world_map.height)
        for field, dimension in (
            ('x', dimensions[0]),
            ('area_width', dimensions[0]),
            ('y', dimensions[1]),
            ('area_height', dimensions[1]),
        ):
            value = getattr(portal, field)
            if value is not None:
                setattr(
                    portal,
                    field,
                    (value * Decimal(dimension)).quantize(
                        Decimal('0.01'),
                        rounding=ROUND_HALF_UP,
                    ),
                )
        portal.save(using=database)


def reverse_portal_registry(apps, schema_editor):
    Portal = apps.get_model('ducky_arenas', 'Portal')
    database = schema_editor.connection.alias
    for portal in Portal.objects.using(database).select_related('destination', 'world_map').all():
        portal.destination_app = portal.destination.owner_app
        portal.destination_url_name = portal.destination.entry_url_name
        portal.save(using=database, update_fields=['destination_app', 'destination_url_name'])
        dimensions = (portal.world_map.width, portal.world_map.height)
        for field, dimension in (
            ('x', dimensions[0]),
            ('area_width', dimensions[0]),
            ('y', dimensions[1]),
            ('area_height', dimensions[1]),
        ):
            value = getattr(portal, field)
            if value is not None:
                setattr(
                    portal,
                    field,
                    (value / Decimal(dimension)).quantize(Decimal('0.000001')),
                )
        portal.save(using=database)


